import{_ as s,o as n,c as m,aN as t}from"./chunks/framework.D31DlcCL.js";const p="/img/math-surplus-deficit-2.svg",g=JSON.parse('{"title":"小学奥数进阶：盈亏问题的三种模型","description":"盈亏问题是小学奥数中的难点。本文通过图解法，带你理清“盈盈”、“亏亏”以及“盈亏”三种核心模型，掌握万能公式。","frontmatter":{"title":"小学奥数进阶：盈亏问题的三种模型","date":"2026-02-08T10:00:00.000Z","categories":["数学"],"tags":["小学数学","奥数","盈亏问题"],"description":"盈亏问题是小学奥数中的难点。本文通过图解法，带你理清“盈盈”、“亏亏”以及“盈亏”三种核心模型，掌握万能公式。","cover":"/img/math-surplus-deficit-2.svg","top_img":"/img/math-surplus-deficit-2.svg","toc_number":true,"katex":true},"headers":[],"relativePath":"posts/primary-math-olympiad-surplus-deficit-2.md","filePath":"posts/primary-math-olympiad-surplus-deficit-2.md","lastUpdated":null}'),l={name:"posts/primary-math-olympiad-surplus-deficit-2.md"};function o(e,a,r,i,c,h){return n(),m("div",null,[...a[0]||(a[0]=[t('<h1 id="小学奥数进阶-盈亏问题的三种模型" tabindex="-1">小学奥数进阶：盈亏问题的三种模型 <a class="header-anchor" href="#小学奥数进阶-盈亏问题的三种模型" aria-label="Permalink to &quot;小学奥数进阶：盈亏问题的三种模型&quot;">​</a></h1><h2 id="一、-什么是盈亏问题" tabindex="-1">一、 什么是盈亏问题？ <a class="header-anchor" href="#一、-什么是盈亏问题" aria-label="Permalink to &quot;一、 什么是盈亏问题？&quot;">​</a></h2><p>把一定数量的物品平均分给一定数量的人，由于分法不同，会出现“盈”（多出）或“亏”（不够）的情况。我们的目标通常是求出<strong>人数</strong>和<strong>物品总数</strong>。</p><hr><h2 id="二、-三大核心模型" tabindex="-1">二、 三大核心模型 <a class="header-anchor" href="#二、-三大核心模型" aria-label="Permalink to &quot;二、 三大核心模型&quot;">​</a></h2><h3 id="_1-一盈一亏-标准型" tabindex="-1">1. 一盈一亏（标准型） <a class="header-anchor" href="#_1-一盈一亏-标准型" aria-label="Permalink to &quot;1. 一盈一亏（标准型）&quot;">​</a></h3><p><strong>例题</strong>：小朋友分糖果，每人分 5 块，多出 10 块（盈）；每人分 7 块，还少 6 块（亏）。问有多少个小朋友？多少块糖果？</p><p><strong>分析</strong>：</p><ul><li>两次分法的单价差：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>7</mn><mo>−</mo><mn>5</mn><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">7 - 5 = 2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">7</span><span class="mbin">−</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">2</span></span></span></span> 块/人。</li><li>总差额：因为一盈一亏，所以总差额是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>0</mn><mo>+</mo><mn>6</mn><mo>=</mo><mn>1</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">10 + 6 = 16</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">6</span></span></span></span> 块。</li><li><strong>公式</strong>：<strong>人数 = (盈 + 亏) ÷ 两次分配差</strong></li><li><strong>计算</strong>：人数 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>6</mn><mo>÷</mo><mn>2</mn><mo>=</mo><mn>8</mn></mrow><annotation encoding="application/x-tex">16 \\div 2 = 8</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">6</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">8</span></span></span></span> 人。</li><li><strong>糖果</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>8</mn><mo>×</mo><mn>5</mn><mo>+</mo><mn>1</mn><mn>0</mn><mo>=</mo><mn>5</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">8 \\times 5 + 10 = 50</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">8</span><span class="mbin">×</span><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span></span></span></span> 块。</li></ul><h3 id="_2-两盈或两亏" tabindex="-1">2. 两盈或两亏 <a class="header-anchor" href="#_2-两盈或两亏" aria-label="Permalink to &quot;2. 两盈或两亏&quot;">​</a></h3><p><strong>例题（两盈）</strong>：每人分 4 块，多 20 块；每人分 6 块，多 4 块。</p><ul><li><strong>分析</strong>：两次都多，总差额是它们的差：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mo>−</mo><mn>4</mn><mo>=</mo><mn>1</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">20 - 4 = 16</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">6</span></span></span></span> 块。</li><li><strong>公式</strong>：<strong>人数 = (大盈 - 小盈) ÷ 两次分配差</strong></li><li><strong>计算</strong>：人数 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>6</mn><mo>÷</mo><mo>(</mo><mn>6</mn><mo>−</mo><mn>4</mn><mo>)</mo><mo>=</mo><mn>8</mn></mrow><annotation encoding="application/x-tex">16 \\div (6 - 4) = 8</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">6</span><span class="mbin">÷</span><span class="mopen">(</span><span class="mord mathrm">6</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">8</span></span></span></span> 人。</li></ul><p><strong>例题（两亏）</strong>：每人分 8 块，少 10 块；每人分 9 块，少 20 块。</p><ul><li><strong>分析</strong>：两次都少，总差额也是它们的差：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mo>−</mo><mn>1</mn><mn>0</mn><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">20 - 10 = 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span> 块。</li><li><strong>公式</strong>：<strong>人数 = (大亏 - 小亏) ÷ 两次分配差</strong></li></ul><hr><h2 id="三、-图解思维-为什么相加或相减" tabindex="-1">三、 图解思维：为什么相加或相减？ <a class="header-anchor" href="#三、-图解思维-为什么相加或相减" aria-label="Permalink to &quot;三、 图解思维：为什么相加或相减？&quot;">​</a></h2><p><img src="'+p+'" alt="盈亏问题进阶图解"></p><ul><li><strong>一盈一亏</strong>：就像一个人往左走，一个往右走，差距是两段距离<strong>相加</strong>。</li><li><strong>同盈同亏</strong>：就像两个人都往同一个方向走，差距是两段距离<strong>相减</strong>。</li></ul><hr><h2 id="四、-进阶变式-隐藏的条件" tabindex="-1">四、 进阶变式：隐藏的条件 <a class="header-anchor" href="#四、-进阶变式-隐藏的条件" aria-label="Permalink to &quot;四、 进阶变式：隐藏的条件&quot;">​</a></h2><p><strong>例题</strong>：某班同学去划船。如果每条船坐 4 人，则多出 1 条船；如果每条船坐 6 人，则少租 2 条船。求有多少个同学？</p><p><strong>转化</strong>：</p><ul><li>“多出 1 条船” 意味着如果按 4 人分，会空出 4 个座位，即 <strong>盈 = 4</strong>。</li><li>“少租 2 条船” 意味着如果按 6 人分，还需要 2 条船的座位，即 <strong>亏 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>6</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">6 \\times 2 = 12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">6</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span></strong>。</li><li>现在变成了标准的一盈一亏问题： <ul><li>人数（船数）= <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>4</mn><mo>+</mo><mn>1</mn><mn>2</mn><mo>)</mo><mo>÷</mo><mo>(</mo><mn>6</mn><mo>−</mo><mn>4</mn><mo>)</mo><mo>=</mo><mn>8</mn></mrow><annotation encoding="application/x-tex">(4 + 12) \\div (6 - 4) = 8</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mopen">(</span><span class="mord mathrm">6</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">8</span></span></span></span> 条船。</li><li>同学数 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>8</mn><mo>×</mo><mn>4</mn><mo>−</mo><mn>4</mn><mo>=</mo><mn>2</mn><mn>8</mn></mrow><annotation encoding="application/x-tex">8 \\times 4 - 4 = 28</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">8</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">8</span></span></span></span> 人（或者 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>8</mn><mo>+</mo><mn>2</mn><mo>)</mo><mo>×</mo><mn>6</mn><mo>=</mo><mn>6</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">(8 + 2) \\times 6 = 60</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">8</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mclose">)</span><span class="mbin">×</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">6</span><span class="mord mathrm">0</span></span></span></span>？不对，重算：每条船坐 4 人多 1 条船，即 4 \\times (船数 - 1)；坐 6 人少 2 条船，即 6 \\times (船数 - 2)。</li><li>方程：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mi>x</mi><mo>−</mo><mn>4</mn><mo>=</mo><mn>6</mn><mi>x</mi><mo>−</mo><mn>1</mn><mn>2</mn><mo>→</mo><mn>2</mn><mi>x</mi><mo>=</mo><mn>8</mn><mo>→</mo><mi>x</mi><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">4x - 4 = 6x - 12 \\rightarrow 2x = 8 \\rightarrow x = 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathit">x</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">6</span><span class="mord mathit">x</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mrel">→</span><span class="mord mathrm">2</span><span class="mord mathit">x</span><span class="mrel">=</span><span class="mord mathrm">8</span><span class="mrel">→</span><span class="mord mathit">x</span><span class="mrel">=</span><span class="mord mathrm">4</span></span></span></span>。</li><li><strong>纠正</strong>：盈亏问题的关键是统一“单位”。这里每条船坐 4 人，多 4 个位置；坐 6 人，少 12 个位置。</li><li>船数 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>4</mn><mo>+</mo><mn>1</mn><mn>2</mn><mo>)</mo><mo>÷</mo><mo>(</mo><mn>6</mn><mo>−</mo><mn>4</mn><mo>)</mo><mo>=</mo><mn>8</mn></mrow><annotation encoding="application/x-tex">(4 + 12) \\div (6 - 4) = 8</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mopen">(</span><span class="mord mathrm">6</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">8</span></span></span></span> 条。</li><li>同学数 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mo>×</mo><mn>8</mn><mo>−</mo><mn>4</mn><mo>=</mo><mn>2</mn><mn>8</mn></mrow><annotation encoding="application/x-tex">4 \\times 8 - 4 = 28</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mbin">×</span><span class="mord mathrm">8</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">8</span></span></span></span> 人。</li></ul></li></ul><hr><h2 id="五、-举一反三-练习题" tabindex="-1">五、 举一反三（练习题） <a class="header-anchor" href="#五、-举一反三-练习题" aria-label="Permalink to &quot;五、 举一反三（练习题）&quot;">​</a></h2><ol><li>老师给学生发练习本。如果每人发 3 本，还剩 19 本；如果每人发 5 本，正好发完。问有多少个学生？多少本练习本？</li><li>搬运工搬运一批瓷砖。如果每人搬 15 块，还剩 30 块；如果每人搬 20 块，还有 2 个人没活干。求有多少个工人和多少块瓷砖？</li></ol><hr><p><em>提示：记住“异号相加，同号相减”！</em></p>',28)])])}const x=s(l,[["render",o]]);export{g as __pageData,x as default};
